"""Generate genuine schema-4 vault fixtures with the released v4 code (commit eeed753).

Usage:
    git worktree add --detach /tmp/v4 eeed753311382047fb2042515a5d2d0f68e94b04
    python -I generate_v4_fixtures.py "/tmp/v4/sovereign-os/sovereign-os 3" <output dir> [fixture names]
    python -I generate_v4_fixtures.py "/tmp/v4/sovereign-os/sovereign-os 3" <output dir> --export v4_clean
    python -I generate_v4_fixtures.py "/tmp/v4/sovereign-os/sovereign-os 3" <output dir> --restore <format-2 backup.json> <name>
With fixture names, only those are (re)generated. `--export` writes `<name>.export.json`, the v4 code's own export of
an existing fixture. `--restore` writes `<name>.sql`, a v4 vault made by the v4 code's trusted restore of a backup.
The v4 project dir is a checkout of eeed753's `sovereign-os/sovereign-os 3` (schema 4, the released ADR-0003 code).
Fixture ids and times are random per run; tests locate items by text, never by id. Each fixture is produced by
that code's own Vault API (and, where a fixture records damage, by the Issue #6 attack itself on an ordinary
default-pragma connection), then written as a lossless SQL dump (see `dump`). Synthetic data only.
"""
import hashlib
import os
import sqlite3
import sys
import tempfile

V4, OUT, ARGS = sys.argv[1], sys.argv[2], sys.argv[3:]
sys.path.insert(0, os.path.join(V4, "src"))
from sovereign import store as v4store   # noqa: E402  (the genuine v4 module)
from sovereign.store import Vault        # noqa: E402

assert v4store.SCHEMA_VERSION == 4, "this generator must run against schema-4 code"
T = "2026-10-01T00:00:00+00:00"


def literal(value):
    if value is None:
        return "NULL"
    if isinstance(value, int):
        return str(value)
    if isinstance(value, float):
        return repr(value)
    if isinstance(value, str):   # hex keeps embedded NUL and every byte exactly
        return f"CAST(X'{value.encode('utf-8').hex()}' AS TEXT)"
    if isinstance(value, bytes):
        return f"X'{value.hex()}'"
    raise TypeError(type(value))


def dump(path):
    """Lossless dump: tables, every row (with rowid for rowid tables), sqlite_sequence, indexes, triggers, user_version."""
    db = sqlite3.connect(path)
    out = ["-- Genuine schema-4 Sovereign vault fixture generated by eeed753 code. Synthetic data only.",
           "PRAGMA foreign_keys=OFF;", "BEGIN;"]
    objects = db.execute("SELECT type, name, sql FROM sqlite_master WHERE sql IS NOT NULL ORDER BY rowid").fetchall()
    tables = [(n, s) for t, n, s in objects if t == "table" and n != "sqlite_sequence"]
    for name, sql in tables:
        out.append(sql + ";")
    for name, _ in tables:
        info = db.execute(f'PRAGMA table_info("{name}")').fetchall()
        cols = [r[1] for r in info]
        int_pk = [r for r in info if r[5]] and len([r for r in info if r[5]]) == 1 and [r for r in info if r[5]][0][2].upper() == "INTEGER"
        without_rowid = db.execute("SELECT sql FROM sqlite_master WHERE name=?", (name,)).fetchone()[0].rstrip().upper().endswith("WITHOUT ROWID")
        names = cols if (int_pk or without_rowid) else ["rowid"] + cols
        select = ", ".join(f'"{c}"' if c != "rowid" else "rowid" for c in names)
        for row in db.execute(f'SELECT {select} FROM "{name}" ORDER BY {"rowid" if not without_rowid else "1"}'):
            out.append(f'INSERT INTO "{name}" ({", ".join(names)}) VALUES ({", ".join(literal(v) for v in row)});')
    if db.execute("SELECT 1 FROM sqlite_master WHERE name='sqlite_sequence'").fetchone():
        out.append("DELETE FROM sqlite_sequence;")
        for name, seq in db.execute("SELECT name, seq FROM sqlite_sequence"):
            out.append(f"INSERT INTO sqlite_sequence (name, seq) VALUES ({literal(name)}, {seq});")
    for kind in ("index", "trigger"):
        for t, name, sql in objects:
            if t == kind:
                out.append(sql + ";")
    out.append(f"PRAGMA user_version={db.execute('PRAGMA user_version').fetchone()[0]};")
    out.append("COMMIT;")
    db.close()
    return "\n".join(out) + "\n"


def v0_base(path, extra=""):
    db = sqlite3.connect(path)
    db.executescript(f"""
        CREATE TABLE records (id TEXT PRIMARY KEY, content TEXT NOT NULL, source TEXT NOT NULL DEFAULT 'manual',
          sensitivity TEXT NOT NULL CHECK(sensitivity IN ('private','sensitive')), status TEXT NOT NULL CHECK(status IN ('active','superseded')),
          created_at TEXT NOT NULL, supersedes_id TEXT);
        CREATE TABLE tombstones (id TEXT PRIMARY KEY, deleted_at TEXT NOT NULL);
        CREATE INDEX ix_records_status ON records(status,created_at);
        INSERT INTO records VALUES ('legacy/1','Legacy synthetic note','manual','private','active','{T}',NULL);
        INSERT INTO tombstones VALUES ('legacy-gone','{T}');
        {extra}
    """)
    db.close()


def fixture(name, build, extra=""):
    d = tempfile.mkdtemp()
    path = os.path.join(d, "vault.db")
    v0_base(path, extra)
    v = Vault(path)                       # genuine v4 migration 0 -> 4
    notes = build(v, path) or ""
    db = sqlite3.connect(path)
    assert db.execute("PRAGMA user_version").fetchone()[0] == 4
    db.close()
    text = dump(path)
    with open(os.path.join(OUT, f"{name}.sql"), "w", encoding="utf-8") as fh:
        fh.write(text)
    print(f"{name}: {len(text)} bytes; sha256 {hashlib.sha256(text.encode()).hexdigest()[:16]} {notes}")


def attacker(path):
    return sqlite3.connect(path, isolation_level=None)   # ordinary connection, default pragmas


def clean(v, path):
    a = v.add("Synthetic note A")
    b = v.add("Synthetic note B, sensitive", "sensitive")
    a2 = v.add("Synthetic note A, corrected", supersedes_id=a["id"])
    ap = v.add_claim("Approved claim on two sources", [a2["id"], "legacy/1"])
    v.transition_claim(ap["id"], "approved", expected_status="proposed")
    ct = v.add_claim("Contested claim", [b["id"]])
    v.transition_claim(ct["id"], "contested", note="unsure", expected_status="proposed")
    rj = v.add_claim("Rejected claim", [a2["id"]])
    v.transition_claim(rj["id"], "rejected", expected_status="proposed")
    old = v.add_claim("Claim to supersede", [a2["id"]])
    v.supersede_claim(old["id"], "Superseding claim", [a2["id"]], expected_status="proposed")
    v.delete_claim(v.add_claim("Claim to forget", [b["id"]])["id"])
    v.delete(v.add("Synthetic note to forget")["id"])
    for _ in range(3):   # a longer legitimate history
        v.transition_claim(ap["id"], "contested", expected_status="approved")
        v.transition_claim(ap["id"], "approved", expected_status="contested")


def partial_link_loss(v, path):
    """F-1: an approved claim on two sources loses one link through the Issue #6 attack before migration."""
    r1, r2, r3 = v.add("Evidence one"), v.add("Evidence two"), v.add("Attacker's evidence")
    c = v.add_claim("Approved claim resting on evidence one AND evidence two", [r1["id"], r2["id"]])
    v.transition_claim(c["id"], "approved", expected_status="proposed")
    db = attacker(path)
    victim = db.execute("SELECT rowid FROM claim_sources WHERE claim_id=? AND record_id=?", (c["id"], r2["id"])).fetchone()[0]
    db.execute("INSERT INTO claims(id,text,origin,status,created_at) VALUES('atk-claim','forged','human','proposed',?)", (T,))
    db.execute("INSERT OR REPLACE INTO claim_sources(rowid,claim_id,record_id) VALUES(?,'atk-claim',?)", (victim, r3["id"]))
    left = db.execute("SELECT count(*) FROM claim_sources WHERE claim_id=?", (c["id"],)).fetchone()[0]
    db.close()
    assert left == 1
    return f"victim claim {c['id']} keeps 1 of 2 links"


def zero_link_loss(v, path):
    """F-2: an approved claim with history loses its only link."""
    r1, r3 = v.add("Only evidence"), v.add("Attacker's evidence")
    c = v.add_claim("Approved claim resting only on 'only evidence'", [r1["id"]])
    v.transition_claim(c["id"], "approved", expected_status="proposed")
    db = attacker(path)
    victim = db.execute("SELECT rowid FROM claim_sources WHERE claim_id=?", (c["id"],)).fetchone()[0]
    db.execute("INSERT INTO claims(id,text,origin,status,created_at) VALUES('atk-claim','forged','human','proposed',?)", (T,))
    db.execute("INSERT OR REPLACE INTO claim_sources(rowid,claim_id,record_id) VALUES(?,'atk-claim',?)", (victim, r3["id"]))
    db.close()
    return f"victim claim {c['id']} keeps 0 links but its history"


def claim_row_replaced(v, path):
    """F-2: an approved claim row is replaced; its links and history are left orphaned (foreign keys off)."""
    r1 = v.add("Evidence for a claim that will be replaced")
    c = v.add_claim("Approved claim whose row will be replaced", [r1["id"]])
    v.transition_claim(c["id"], "approved", expected_status="proposed")
    db = attacker(path)
    victim = db.execute("SELECT rowid FROM claims WHERE id=?", (c["id"],)).fetchone()[0]
    db.execute("INSERT OR REPLACE INTO claims(rowid,id,text,origin,status,created_at) VALUES(?,'atk-claim','forged','human','proposed',?)", (victim, T))
    db.close()
    return f"claim {c['id']} replaced; its links and events are orphaned"


def check_bypass(v, path):
    """F-3: a record with a status outside the CHECK set, written by an ordinary connection that disables CHECKs."""
    db = attacker(path)
    db.execute("PRAGMA ignore_check_constraints=ON")
    db.execute("INSERT INTO records(id,content,source,sensitivity,status,created_at) VALUES('odd-status','Note in an unknown state','manual','private','archived',?)", (T,))
    db.close()
    # v4 refuses to create a claim on non-active evidence through the API; attach one by raw SQL as a reviewer would.
    db = attacker(path)
    h = v4store.evidence_hash(dict(zip(("id","content","source","sensitivity","created_at","supersedes_id"),
                                        ("odd-status","Note in an unknown state","manual","private",T,None))))
    db.execute("INSERT INTO claims(id,text,origin,status,created_at) VALUES('c-odd','Claim resting on a note in an unknown state','human','proposed',?)", (T,))
    db.execute("INSERT INTO claim_sources(claim_id,record_id,evidence_sha256) VALUES('c-odd','odd-status',?)", (h,))
    db.execute("INSERT INTO claim_events(claim_id,from_status,to_status,actor,at) VALUES('c-odd',NULL,'proposed','human',?)", (T,))
    db.close()
    v.transition_claim("c-odd", "approved", expected_status="proposed")   # v4's domain check accepts 'archived' evidence
    return "record status 'archived'; claim c-odd approved on it"


def nul_lengths(v, path):
    """F-4: values whose SQLite length() stops at an embedded NUL while Python counts every character."""
    db = attacker(path)
    db.execute("INSERT INTO records(id,content,source,sensitivity,status,created_at) VALUES(?,?, 'manual','private','active',?)",
               ("nul-record", "N" + "\x00" + "x" * 10050, T))
    db.close()
    r = v.add("Ordinary evidence for a NUL-length claim")
    db = attacker(path)
    db.execute("INSERT INTO claims(id,text,origin,status,created_at) VALUES('c-nul',?,'human','proposed',?)", ("C" + "\x00" + "y" * 2500, T))
    db.execute("INSERT INTO claim_sources(claim_id,record_id,evidence_sha256) VALUES('c-nul',?,?)", (r["id"], v4store.evidence_hash(r)))
    db.execute("INSERT INTO claim_events(claim_id,from_status,to_status,actor,at) VALUES('c-nul',NULL,'proposed','human',?)", (T,))
    db.close()
    return "record content 10052 chars and claim text 2502 chars, each with an embedded NUL"


def nul_short(v, path):
    """D-C: current (non-legacy) text holding an embedded NUL but within every length bound, which v4 accepts."""
    r = v.add("Ordinary evidence for a short NUL claim")
    db = attacker(path)
    db.execute("INSERT INTO claims(id,text,origin,status,created_at) VALUES('c-short-nul',?,'human','proposed',?)", ("Short\x00claim", T))
    db.execute("INSERT INTO claim_sources(claim_id,record_id,evidence_sha256) VALUES('c-short-nul',?,?)", (r["id"], v4store.evidence_hash(r)))
    db.execute("INSERT INTO claim_events(claim_id,from_status,to_status,actor,at) VALUES('c-short-nul',NULL,'proposed','human',?)", (T,))
    db.close()
    return "claim text 'Short<NUL>claim' (11 characters)"


def legacy_nul(v, path):
    """D-C: an ADR-0002 legacy record whose content holds an embedded NUL, migrated by v4 with legacy = 1."""
    return "legacy record 'legacy/nul'"


def load(path, name):
    db = sqlite3.connect(path)
    db.execute("PRAGMA ignore_check_constraints=ON")
    with open(os.path.join(OUT, f"{name}.sql"), encoding="utf-8") as fh:
        db.executescript(fh.read())
    db.close()


os.makedirs(OUT, exist_ok=True)
if ARGS[:1] == ["--export"]:            # the v4 code's own export of an existing fixture (it opens v4 without migrating)
    import json
    for name in ARGS[1:]:
        path = os.path.join(tempfile.mkdtemp(), "vault.db")
        load(path, name)
        export = Vault(path).export()
        with open(os.path.join(OUT, f"{name}.export.json"), "w", encoding="utf-8") as fh:
            json.dump(export, fh, ensure_ascii=False, indent=1, sort_keys=True)
            fh.write("\n")
        print(f"{name}.export.json: schema {export['schema']}, {len(export['claims'])} claims")
elif ARGS[:1] == ["--restore"]:         # a v4 vault made by the v4 code's trusted restore of a given backup
    import json
    source, name = ARGS[1], ARGS[2]
    with open(source, encoding="utf-8") as fh:
        backup = json.load(fh)
    path = os.path.join(tempfile.mkdtemp(), "vault.db")
    result = Vault(path).restore_trusted(backup)
    text = dump(path)
    with open(os.path.join(OUT, f"{name}.sql"), "w", encoding="utf-8") as fh:
        fh.write(text)
    print(f"{name}: {len(text)} bytes; sha256 {hashlib.sha256(text.encode()).hexdigest()[:16]} restore {result}")
else:
    builders = {"v4_clean": (clean, ""), "v4_partial_link_loss": (partial_link_loss, ""),
                "v4_zero_link_loss": (zero_link_loss, ""), "v4_claim_row_replaced": (claim_row_replaced, ""),
                "v4_check_bypass": (check_bypass, ""), "v4_nul_lengths": (nul_lengths, ""), "v4_nul_short": (nul_short, ""),
                "v4_legacy_nul": (legacy_nul, "INSERT INTO records VALUES ('legacy/nul',CAST(X'4c6567616379006e6f7465' AS TEXT),"
                                              f"'manual','private','active','{T}',NULL);")}
    for name in ARGS or list(builders):
        build, extra = builders[name]
        fixture(name, build, extra)
